import itertools

def is_valid(edges):
    # Check if all vertices have degree 4
    degrees = [0] * 8
    for u, v in edges:
        degrees[u] += 1
        degrees[v] += 1
    if any(d != 4 for d in degrees):
        return False

    # Check for triangles (girth >= 4)
    adj = [[] for _ in range(8)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    for i in range(8):
        for j in adj[i]:
            for k in adj[j]:
                if k != i and i in adj[k]:
                    return False
    return True

# K_{4,4} construction
A = [0, 1, 2, 3]
B = [4, 5, 6, 7]
edges = []
for u in A:
    for v in B:
        edges.append((u, v))

# Check fixed edges
fixed_edges = [(0, 4), (0, 7), (2, 4)]
for edge in fixed_edges:
    if edge not in edges:
        print(f"Fixed edge {edge} not in K_{{4,4}}")
        break
else:
    print("All fixed edges are in K_{4,4}")

# Check validity
if is_valid(edges):
    print("K_{4,4} is valid")
    print(edges)
else:
    print("K_{4,4} is not valid")
